package com.lostf1sh.pixelplayeross.data.rhythm

import java.io.File
import kotlinx.serialization.json.Json
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Golden fixture pulled from the 0.4.3-pisces.1 debug build installed on the user's phone
 * (`com.lostf1sh.pixelplayeross.debug`, `files/rhythm/charts`), song "迎着风向前冲", 172.875 s.
 *
 * The master was generated by that build on 2026-11-07 and carries the era's single timing point
 * `(139 ms, 352.3218036863423 ms)` = 170.2989 BPM; the Easy chart is the 544-note chart the user
 * compares new builds against. The test replays derivation from the stored master, so it pins the
 * frozen quantization independent of today's analysis: a fresh master may differ in BPM / phase
 * and is deliberately not asserted here.
 */
class RhythmClassicGridLegacyFixtureTest {

    private val json = Json { ignoreUnknownKeys = true }

    private fun resource(name: String): File {
        val url = requireNotNull(javaClass.classLoader?.getResource("rhythm/$name")) {
            "missing test resource rhythm/$name"
        }
        return File(url.toURI())
    }

    private fun chart(name: String): RhythmChart =
        json.decodeFromString(RhythmChart.serializer(), resource(name).readText())

    @Test
    fun classicEasyReproducesTheFiveHundredFortyFourNoteChart() {
        val master = chart("yingzhefeng-043-master.json")
        val expected = chart("yingzhefeng-043-easy-544.expected.json")

        assertEquals(1306, master.noteCount())
        assertEquals(1, master.timing.size)
        assertEquals(139, master.timing.single().timeMs)
        assertEquals(352.321804, master.timing.single().beatMs, 1e-6)

        val derived = RhythmClassicGridDeriver
            .derive(master, DspDifficulty.EASY, LaneStrategy.BAND_ORDER, maxChord = 2)
            .withoutLeadIn()

        assertEquals(544, expected.noteCount())
        assertEquals(expected.noteCount(), derived.noteCount())
        // The stored chart was trimmed after ids were assigned, so ids are not comparable;
        // time and lane are the playable content and must match exactly.
        assertEquals(
            expected.notes.map { it.timeMs to it.lane },
            derived.notes.map { it.timeMs to it.lane },
        )
    }
}
